INSERT INTO standard_templates (key,name,area,description,role_description,version,status,tasks_json,start_requirements_json,readiness_criteria_json) VALUES
('bos-log-001','Magazynier','Magazyn i logistyka','Roboczy wzór BOS dla stanowiska: Magazynier. Wymaga dostosowania do organizacji przed publikacją.','Przyjmowanie, rozmieszczanie, kompletowanie i przekazywanie towarów.',1,'HIDDEN','[{"name":"Przekazanie zmiany","execution":"Odczytaj zgłoszone braki, zadania otwarte i stan stref składowania; wskaż elementy wymagające interwencji.","readyWhen":"Lista zadań i odchyleń ma przypisany status.","hint":"Weryfikacja czynności «Przekazanie zmiany»: sprawdź na rzeczywistym przykładzie, czy lista zadań i odchyleń ma przypisany status. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":false},{"name":"Przyjęcie towaru","execution":"Porównaj dokument dostawy z etykietami, ilością i widocznym stanem opakowań; rozbieżności odseparuj do wyjaśnienia.","readyWhen":"Pozycje zgodne są potwierdzone, a niezgodne oznaczone.","hint":"Weryfikacja czynności «Przyjęcie towaru»: sprawdź na rzeczywistym przykładzie, czy pozycje zgodne są potwierdzone, a niezgodne oznaczone. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Rozmieszczenie towaru","execution":"Odczytaj wskazanie lokalizacji w systemie i umieść towar zgodnie z zasadami magazynu, bez blokowania dróg komunikacyjnych.","readyWhen":"Lokalizacja i ilość odpowiadają zapisowi systemowemu.","hint":"Weryfikacja czynności «Rozmieszczenie towaru»: sprawdź na rzeczywistym przykładzie, czy lokalizacja i ilość odpowiadają zapisowi systemowemu. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Kompletacja","execution":"Pobierz produkty według listy, kontrolując kod, wariant i ilość przy każdej pozycji.","readyWhen":"Wszystkie pobrania są potwierdzone bez niewyjaśnionych różnic.","hint":"Weryfikacja czynności «Kompletacja»: sprawdź na rzeczywistym przykładzie, czy wszystkie pobrania są potwierdzone bez niewyjaśnionych różnic. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Przekazanie wydania","execution":"Porównaj zestaw z dokumentem, oznacz jednostkę wysyłkową i przekaż ją do wskazanej strefy.","readyWhen":"Wydanie jest identyfikowalne i przyjęte przez następny etap.","hint":"Weryfikacja czynności «Przekazanie wydania»: sprawdź na rzeczywistym przykładzie, czy wydanie jest identyfikowalne i przyjęte przez następny etap. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true}]'::jsonb,'[{"category":"INSTRUCTIONS","requirement":"Przed rozpoczęciem pracy na stanowisku „Magazynier” dostępne są aktualne instrukcje i zakres odpowiedzialności dla czynności „Przekazanie zmiany” oraz „Przyjęcie towaru”."},{"category":"TOOLS","requirement":"Zapewniono narzędzia, materiały i dostęp do rejestrów potrzebnych do wykonania czynności „Rozmieszczenie towaru”; prowadzący potwierdził ich dostępność."},{"category":"OTHER","requirement":"Organizacja potwierdziła wymagane szkolenia, uprawnienia, zabezpieczenia i ścieżkę eskalacji dla stanowiska „Magazynier” przed dopuszczeniem do zadań."}]'::jsonb,'[{"criterion":"Na obserwowanej próbie pracownik wykonuje czynność „Przyjęcie towaru” i uzyskuje wynik: Pozycje zgodne są potwierdzone, a niezgodne oznaczone. Liczbę prób i dopuszczalne odchylenia zatwierdza organizacja.","verificationMethod":"OBSERVATION"},{"criterion":"Pracownik wyjaśnia, jak postępuje przy niezgodności podczas czynności „Rozmieszczenie towaru”, i wskazuje osobę lub kanał eskalacji zgodny z lokalną procedurą.","verificationMethod":"CONTROL_QUESTIONS"},{"criterion":"W samodzielnej próbie czynności „Kompletacja” uzyskano wynik: Wszystkie pobrania są potwierdzone bez niewyjaśnionych różnic. Wynik zostaje udokumentowany przez oceniającego.","verificationMethod":"INDEPENDENT_TASK"}]'::jsonb),
('bos-log-002','Pracownik kompletacji zamówień','Magazyn i logistyka','Roboczy wzór BOS dla stanowiska: Pracownik kompletacji zamówień. Wymaga dostosowania do organizacji przed publikacją.','Przygotowanie zamówień do wysyłki zgodnie z listą i zasadami identyfikowalności.',1,'HIDDEN','[{"name":"Przygotowanie zlecenia","execution":"Sprawdź identyfikator zamówienia, wymagany termin, listę pozycji i sposób pakowania.","readyWhen":"Lista jest czytelna i kompletna.","hint":"Weryfikacja czynności «Przygotowanie zlecenia»: sprawdź na rzeczywistym przykładzie, czy lista jest czytelna i kompletna. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":false},{"name":"Pobranie","execution":"Skanuj lub potwierdzaj kod produktu i ilość przy pobraniu z lokalizacji.","readyWhen":"Każda pozycja ma potwierdzony kod i ilość.","hint":"Weryfikacja czynności «Pobranie»: sprawdź na rzeczywistym przykładzie, czy każda pozycja ma potwierdzony kod i ilość. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Kontrola wariantów","execution":"Porównaj rozmiary, kolory, partie i pozostałe cechy z zamówieniem.","readyWhen":"Nie ma niepotwierdzonych zamienników ani różnic.","hint":"Weryfikacja czynności «Kontrola wariantów»: sprawdź na rzeczywistym przykładzie, czy nie ma niepotwierdzonych zamienników ani różnic. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Pakowanie","execution":"Dobierz opakowanie i zabezpieczenie zgodnie z wymaganiami produktu; umieść prawidłową etykietę.","readyWhen":"Przesyłka jest zabezpieczona i jednoznacznie oznaczona.","hint":"Weryfikacja czynności «Pakowanie»: sprawdź na rzeczywistym przykładzie, czy przesyłka jest zabezpieczona i jednoznacznie oznaczona. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Przekazanie","execution":"Odnotuj przekazanie paczki do strefy wysyłkowej i zgłoś wyjątki.","readyWhen":"Status zamówienia jest aktualny.","hint":"Weryfikacja czynności «Przekazanie»: sprawdź na rzeczywistym przykładzie, czy status zamówienia jest aktualny. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":false}]'::jsonb,'[{"category":"INSTRUCTIONS","requirement":"Przed rozpoczęciem pracy na stanowisku „Pracownik kompletacji zamówień” dostępne są aktualne instrukcje i zakres odpowiedzialności dla czynności „Przygotowanie zlecenia” oraz „Pobranie”."},{"category":"TOOLS","requirement":"Zapewniono narzędzia, materiały i dostęp do rejestrów potrzebnych do wykonania czynności „Kontrola wariantów”; prowadzący potwierdził ich dostępność."},{"category":"OTHER","requirement":"Organizacja potwierdziła wymagane szkolenia, uprawnienia, zabezpieczenia i ścieżkę eskalacji dla stanowiska „Pracownik kompletacji zamówień” przed dopuszczeniem do zadań."}]'::jsonb,'[{"criterion":"Na obserwowanej próbie pracownik wykonuje czynność „Pobranie” i uzyskuje wynik: Każda pozycja ma potwierdzony kod i ilość. Liczbę prób i dopuszczalne odchylenia zatwierdza organizacja.","verificationMethod":"OBSERVATION"},{"criterion":"Pracownik wyjaśnia, jak postępuje przy niezgodności podczas czynności „Kontrola wariantów”, i wskazuje osobę lub kanał eskalacji zgodny z lokalną procedurą.","verificationMethod":"CONTROL_QUESTIONS"},{"criterion":"W samodzielnej próbie czynności „Pakowanie” uzyskano wynik: Przesyłka jest zabezpieczona i jednoznacznie oznaczona. Wynik zostaje udokumentowany przez oceniającego.","verificationMethod":"INDEPENDENT_TASK"}]'::jsonb),
('bos-log-003','Koordynator magazynu','Magazyn i logistyka','Roboczy wzór BOS dla stanowiska: Koordynator magazynu. Wymaga dostosowania do organizacji przed publikacją.','Organizacja przepływu towaru i przydziału pracy w magazynie.',1,'HIDDEN','[{"name":"Ocena obciążenia","execution":"Zestaw zlecenia, obsadę i dostępność stref na początku zmiany.","readyWhen":"Znane są priorytety i ograniczenia.","hint":"Weryfikacja czynności «Ocena obciążenia»: sprawdź na rzeczywistym przykładzie, czy znane są priorytety i ograniczenia. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":false},{"name":"Planowanie","execution":"Rozdziel zadania według terminu, kompetencji i dostępnych zasobów.","readyWhen":"Każde zadanie ma wykonawcę i termin.","hint":"Weryfikacja czynności «Planowanie»: sprawdź na rzeczywistym przykładzie, czy każde zadanie ma wykonawcę i termin. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Kontrola przepływu","execution":"Porównuj realizację z planem i identyfikuj zatory w przyjęciu, kompletacji i wydaniu.","readyWhen":"Odchylenia mają opisane działanie korygujące.","hint":"Weryfikacja czynności «Kontrola przepływu»: sprawdź na rzeczywistym przykładzie, czy odchylenia mają opisane działanie korygujące. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Eskalacja","execution":"Zgłoś niedobory, awarie lub błędy właściwej osobie; zapisz decyzję.","readyWhen":"Istnieje właściciel i status problemu.","hint":"Weryfikacja czynności «Eskalacja»: sprawdź na rzeczywistym przykładzie, czy istnieje właściciel i status problemu. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Przekazanie zmiany","execution":"Przekaż wyniki, zaległości i ryzyka kolejnej zmianie.","readyWhen":"Odbiorca potwierdził przejęcie otwartych spraw.","hint":"Weryfikacja czynności «Przekazanie zmiany»: sprawdź na rzeczywistym przykładzie, czy odbiorca potwierdził przejęcie otwartych spraw. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":false}]'::jsonb,'[{"category":"INSTRUCTIONS","requirement":"Przed rozpoczęciem pracy na stanowisku „Koordynator magazynu” dostępne są aktualne instrukcje i zakres odpowiedzialności dla czynności „Ocena obciążenia” oraz „Planowanie”."},{"category":"TOOLS","requirement":"Zapewniono narzędzia, materiały i dostęp do rejestrów potrzebnych do wykonania czynności „Kontrola przepływu”; prowadzący potwierdził ich dostępność."},{"category":"OTHER","requirement":"Organizacja potwierdziła wymagane szkolenia, uprawnienia, zabezpieczenia i ścieżkę eskalacji dla stanowiska „Koordynator magazynu” przed dopuszczeniem do zadań."}]'::jsonb,'[{"criterion":"Na obserwowanej próbie pracownik wykonuje czynność „Planowanie” i uzyskuje wynik: Każde zadanie ma wykonawcę i termin. Liczbę prób i dopuszczalne odchylenia zatwierdza organizacja.","verificationMethod":"OBSERVATION"},{"criterion":"Pracownik wyjaśnia, jak postępuje przy niezgodności podczas czynności „Kontrola przepływu”, i wskazuje osobę lub kanał eskalacji zgodny z lokalną procedurą.","verificationMethod":"CONTROL_QUESTIONS"},{"criterion":"W samodzielnej próbie czynności „Eskalacja” uzyskano wynik: Istnieje właściciel i status problemu. Wynik zostaje udokumentowany przez oceniającego.","verificationMethod":"INDEPENDENT_TASK"}]'::jsonb),
('bos-log-004','Operator wózka jezdniowego (wymaga weryfikacji uprawnień)','Magazyn i logistyka','Roboczy wzór BOS dla stanowiska: Operator wózka jezdniowego (wymaga weryfikacji uprawnień). Wymaga dostosowania do organizacji przed publikacją.','Wykonywanie zadań na stanowisku operator wózka jezdniowego (wymaga weryfikacji uprawnień) zgodnie z wymaganiami organizacji.',1,'HIDDEN','[{"name":"Kontrola uprawnień","execution":"Potwierdź wymagane kwalifikacje, upoważnienie pracodawcy i dopuszczenie do obsługi konkretnego urządzenia.","readyWhen":"Dokumenty i dopuszczenie są aktualne.","hint":"Weryfikacja czynności «Kontrola uprawnień»: sprawdź na rzeczywistym przykładzie, czy dokumenty i dopuszczenie są aktualne. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Kontrola przed użyciem","execution":"Wykonaj kontrolę wózka zgodnie z instrukcją producenta i zakładu; zgłoś usterki.","readyWhen":"Urządzenie jest dopuszczone do eksploatacji.","hint":"Weryfikacja czynności «Kontrola przed użyciem»: sprawdź na rzeczywistym przykładzie, czy urządzenie jest dopuszczone do eksploatacji. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Transport ładunku","execution":"Zweryfikuj masę, stabilność i trasę; wykonaj przewóz według zasad zakładowych.","readyWhen":"Ładunek przemieszcza się bez naruszenia stref bezpieczeństwa.","hint":"Weryfikacja czynności «Transport ładunku»: sprawdź na rzeczywistym przykładzie, czy ładunek przemieszcza się bez naruszenia stref bezpieczeństwa. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Odstawienie","execution":"Umieść ładunek we wskazanym miejscu, potwierdź lokalizację.","readyWhen":"Lokalizacja i stan ładunku są zgodne.","hint":"Weryfikacja czynności «Odstawienie»: sprawdź na rzeczywistym przykładzie, czy lokalizacja i stan ładunku są zgodne. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Wyłączenie","execution":"Zaparkuj i zabezpiecz urządzenie zgodnie z instrukcją.","readyWhen":"Wózek został bezpiecznie przekazany lub odstawiony.","hint":"Weryfikacja czynności «Wyłączenie»: sprawdź na rzeczywistym przykładzie, czy wózek został bezpiecznie przekazany lub odstawiony. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true}]'::jsonb,'[{"category":"INSTRUCTIONS","requirement":"Przed rozpoczęciem pracy na stanowisku „Operator wózka jezdniowego (wymaga weryfikacji uprawnień)” dostępne są aktualne instrukcje i zakres odpowiedzialności dla czynności „Kontrola uprawnień” oraz „Kontrola przed użyciem”."},{"category":"TOOLS","requirement":"Zapewniono narzędzia, materiały i dostęp do rejestrów potrzebnych do wykonania czynności „Transport ładunku”; prowadzący potwierdził ich dostępność."},{"category":"OTHER","requirement":"Organizacja potwierdziła wymagane szkolenia, uprawnienia, zabezpieczenia i ścieżkę eskalacji dla stanowiska „Operator wózka jezdniowego (wymaga weryfikacji uprawnień)” przed dopuszczeniem do zadań."}]'::jsonb,'[{"criterion":"Na obserwowanej próbie pracownik wykonuje czynność „Kontrola przed użyciem” i uzyskuje wynik: Urządzenie jest dopuszczone do eksploatacji. Liczbę prób i dopuszczalne odchylenia zatwierdza organizacja.","verificationMethod":"OBSERVATION"},{"criterion":"Pracownik wyjaśnia, jak postępuje przy niezgodności podczas czynności „Transport ładunku”, i wskazuje osobę lub kanał eskalacji zgodny z lokalną procedurą.","verificationMethod":"CONTROL_QUESTIONS"},{"criterion":"W samodzielnej próbie czynności „Odstawienie” uzyskano wynik: Lokalizacja i stan ładunku są zgodne. Wynik zostaje udokumentowany przez oceniającego.","verificationMethod":"INDEPENDENT_TASK"}]'::jsonb),
('bos-log-005','Spedytor','Magazyn i logistyka','Roboczy wzór BOS dla stanowiska: Spedytor. Wymaga dostosowania do organizacji przed publikacją.','Wykonywanie zadań na stanowisku spedytor zgodnie z wymaganiami organizacji.',1,'HIDDEN','[{"name":"Przyjęcie zlecenia","execution":"Sprawdź relację, rodzaj ładunku, terminy, wymagane dokumenty i ograniczenia przewozu.","readyWhen":"Zlecenie ma komplet parametrów.","hint":"Weryfikacja czynności «Przyjęcie zlecenia»: sprawdź na rzeczywistym przykładzie, czy zlecenie ma komplet parametrów. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":false},{"name":"Dobór przewozu","execution":"Porównaj możliwości przewoźników z warunkami zlecenia i zaakceptowanym budżetem.","readyWhen":"Wybór ma udokumentowane uzasadnienie.","hint":"Weryfikacja czynności «Dobór przewozu»: sprawdź na rzeczywistym przykładzie, czy wybór ma udokumentowane uzasadnienie. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Potwierdzenie","execution":"Uzgodnij załadunek, rozładunek i odpowiedzialności stron.","readyWhen":"Strony potwierdziły warunki.","hint":"Weryfikacja czynności «Potwierdzenie»: sprawdź na rzeczywistym przykładzie, czy strony potwierdziły warunki. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Monitoring","execution":"Aktualizuj status i rejestruj opóźnienia lub wyjątki.","readyWhen":"Zleceniodawca zna istotne odchylenia.","hint":"Weryfikacja czynności «Monitoring»: sprawdź na rzeczywistym przykładzie, czy zleceniodawca zna istotne odchylenia. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":true},{"name":"Rozliczenie","execution":"Zbierz potwierdzenia wykonania i przekaż dokumenty do rozliczenia.","readyWhen":"Dokumentacja przewozu jest kompletna.","hint":"Weryfikacja czynności «Rozliczenie»: sprawdź na rzeczywistym przykładzie, czy dokumentacja przewozu jest kompletna. Zapisz wynik i ewentualną niezgodność; liczbę prób i próg zaliczenia określa organizacja.","isCritical":false}]'::jsonb,'[{"category":"INSTRUCTIONS","requirement":"Przed rozpoczęciem pracy na stanowisku „Spedytor” dostępne są aktualne instrukcje i zakres odpowiedzialności dla czynności „Przyjęcie zlecenia” oraz „Dobór przewozu”."},{"category":"TOOLS","requirement":"Zapewniono narzędzia, materiały i dostęp do rejestrów potrzebnych do wykonania czynności „Potwierdzenie”; prowadzący potwierdził ich dostępność."},{"category":"OTHER","requirement":"Organizacja potwierdziła wymagane szkolenia, uprawnienia, zabezpieczenia i ścieżkę eskalacji dla stanowiska „Spedytor” przed dopuszczeniem do zadań."}]'::jsonb,'[{"criterion":"Na obserwowanej próbie pracownik wykonuje czynność „Dobór przewozu” i uzyskuje wynik: Wybór ma udokumentowane uzasadnienie. Liczbę prób i dopuszczalne odchylenia zatwierdza organizacja.","verificationMethod":"OBSERVATION"},{"criterion":"Pracownik wyjaśnia, jak postępuje przy niezgodności podczas czynności „Potwierdzenie”, i wskazuje osobę lub kanał eskalacji zgodny z lokalną procedurą.","verificationMethod":"CONTROL_QUESTIONS"},{"criterion":"W samodzielnej próbie czynności „Monitoring” uzyskano wynik: Zleceniodawca zna istotne odchylenia. Wynik zostaje udokumentowany przez oceniającego.","verificationMethod":"INDEPENDENT_TASK"}]'::jsonb),
